/** Opaque identity for one admitted byte resource. Equal bytes may have different identities. */
type ResourceId = `res_${string}`;

type BlobRef = {
    readonly kind: "blob";
    /** One admitted resource instance. Equal bytes admitted twice keep distinct identities. */
    readonly resource: ResourceId;
    readonly size: number;
    readonly mediaType: string;
};

type SourceRange = {
    readonly start: number;
    readonly end: number;
};

type SourceUnit = {
    /** Workspace-canonical identity used only for recursion and diagnostics. */
    readonly id: string;
    readonly name: string;
    /** Opaque source payload. Its selected Frontend alone decides how to decode it. */
    readonly bytes: Uint8Array;
};
/** A Workspace resolution. The Frontend choice is explicit and never guessed by the compiler. */
type ResolvedSource = {
    readonly unit: SourceUnit;
    readonly frontend: string;
};
type SourceImportRequest = {
    readonly from: string;
    readonly alias: string;
    readonly range?: SourceRange;
};
type SourceAssetRequest = {
    readonly from: string;
    readonly mediaType: string;
    /** Package-owned bytes handed to the Workspace for identity and attachment ownership. */
    readonly bytes?: Uint8Array;
    readonly range?: SourceRange;
};
type ResolvedSourceAsset = {
    readonly artifact: BlobRef;
};
type Awaitable<T> = T | Promise<T>;
type SourceResolver = (importer: SourceUnit, request: SourceImportRequest) => Awaitable<ResolvedSource>;
type SourceAssetResolver = (importer: SourceUnit, request: SourceAssetRequest) => Awaitable<ResolvedSourceAsset>;

/** Repeatably openable transfer bytes admitted by the selected Workspace. */
type BlobAttachment = {
    readonly artifact: BlobRef;
    /** Stable external address, when the Workspace supplies a file by reference. */
    readonly location?: string;
    open(): Awaitable<AsyncIterable<Uint8Array>>;
};
/** One isolated, read-once definition session for exactly one compilation. */
interface WorkspaceSession {
    readonly entry: ResolvedSource;
    readonly resolveSource: SourceResolver;
    readonly resolveAsset: SourceAssetResolver;
    attachments(): Awaitable<readonly BlobAttachment[]>;
}
/** Replaceable definition environment: filesystem, browser, Git, memory or remote workspace. */
interface Workspace {
    open(entryLocator: string): Awaitable<WorkspaceSession>;
}
declare class WorkspaceError extends Error {
    readonly code: string;
    readonly subject: string | undefined;
    constructor(code: string, message: string, subject?: string);
}

export { WorkspaceError };
export type { BlobAttachment, Workspace, WorkspaceSession };
